// Ericka booking tools: ElevenLabs mid-call tool webhook -> booking RPCs.
// Design: docs/BOOKING.md.
//
// BEFORE ACTIVATING, replace the three placeholders below:
//   SUPABASE_URL  = https://phtmarvmovozydxipmat.supabase.co  (the CRM project)
//   SERVICE_KEY   = Supabase Dashboard -> Settings -> API Keys -> service_role (secret)
//   MIRROR_KEY    = same shared-secret convention as ghl-stage-sync; configure the
//                   ElevenLabs tool to send it as the X-Mirror-Key header.
//
// Response mode is "last node" on purpose: Ericka reads this JSON synchronously
// mid-call and only offers windows that come back in `open`.
//
// Body (JSON): { action, sub_account_id, ... }
//   action=check  -> { slot_date? (default: today, Phoenix), days? (default 7) }
//   action=book   -> { slot_date, window, customer_name, customer_phone?, lead_id? }
//   action=cancel -> { appointment_id }

const SUPABASE_URL = 'PASTE_PROJECT_URL_HERE';
const SERVICE_KEY = 'PASTE_SERVICE_ROLE_KEY_HERE';
const MIRROR_KEY = 'PASTE_SHARED_SECRET_HERE';

const req = items[0].json;
const headersIn = req.headers ?? {};
const body = req.body ?? req;

if ((headersIn['x-mirror-key'] ?? '') !== MIRROR_KEY) {
  throw new Error('Rejected: bad X-Mirror-Key.');
}

const sbHeaders = (extra = {}) => ({
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  'Content-Type': 'application/json',
  ...extra,
});

// One timezone: America/Phoenix (no DST). All dates are plain YYYY-MM-DD.
const phoenixToday = () =>
  new Date().toLocaleDateString('en-CA', { timeZone: 'America/Phoenix' });
const addDays = (iso, n) => {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
};

const action = String(body.action ?? '').toLowerCase();
const subAccountId = body.sub_account_id;
if (!subAccountId) throw new Error('Missing sub_account_id.');

if (action === 'check') {
  const from = body.slot_date ?? phoenixToday();
  const days = Math.min(Math.max(parseInt(body.days ?? '7', 10) || 7, 1), 30);
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url:
      `${SUPABASE_URL}/rest/v1/booking_slots` +
      `?sub_account_id=eq.${encodeURIComponent(subAccountId)}` +
      `&slot_date=gte.${from}&slot_date=lte.${addDays(from, days)}` +
      `&order=slot_date.asc&select=slot_date,window,capacity,booked_count`,
    headers: sbHeaders(),
    json: true,
  });
  const open = (rows ?? [])
    .filter((r) => r.booked_count < r.capacity)
    .map((r) => ({ date: r.slot_date, window: r.window, spots: r.capacity - r.booked_count }));
  return [{ json: { open } }];
}

if (action === 'book') {
  // book_slot returns the new appointment_id, or NULL when the window filled
  // (or was never provisioned) between the check and this call.
  const appointmentId = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/rpc/book_slot`,
    headers: sbHeaders(),
    body: {
      p_sub_account_id: subAccountId,
      p_slot_date: body.slot_date,
      p_window: body.window,
      p_customer_name: body.customer_name ?? 'Unknown caller',
      p_customer_phone: body.customer_phone ?? '',
      p_lead_id: body.lead_id ?? null,
    },
    json: true,
  });
  if (!appointmentId) {
    return [{
      json: {
        booked: false,
        reason: 'window_full_or_missing',
        slot_date: body.slot_date,
        window: body.window,
      },
    }];
  }
  return [{ json: { booked: true, appointment_id: appointmentId, slot_date: body.slot_date, window: body.window } }];
}

if (action === 'cancel') {
  const cancelled = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/rpc/release_slot`,
    headers: sbHeaders(),
    body: { p_appointment_id: body.appointment_id },
    json: true,
  });
  return [{ json: { cancelled: cancelled === true } }];
}

throw new Error(`Unknown action: ${action}`);
